package com.portfolio.features.project.controller; import com.portfolio.common.api.ApiResponse; import com.portfolio.features.project.dto.*; import com.portfolio.features.project.entity.Project; import com.portfolio.features.project.service.ProjectService; import com.portfolio.features.user.service.UserService; import jakarta.validation.Valid; import java.util.*; import lombok.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/projects") @RequiredArgsConstructor public class ProjectController {private final ProjectService service;private final UserService users;private ProjectResponse response(Project p){return new ProjectResponse(p.getId(),p.getTitle(),p.getSlug(),p.getShortDescription(),p.getDescription(),p.getThumbnailUrl(),p.getGithubUrl(),p.getDemoUrl(),p.isFeatured(),p.getSortOrder(),p.getTechnologies().stream().map(t->t.getTechnology()).toList());}@GetMapping public ApiResponse<List<ProjectResponse>> list(@AuthenticationPrincipal Jwt j){return ApiResponse.success("Projects retrieved successfully.",service.list(users.synchronize(j)).stream().map(this::response).toList());}@GetMapping("/{id}") public ApiResponse<ProjectResponse> get(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){return ApiResponse.success("Project retrieved successfully.",response(service.get(users.synchronize(j),id)));}@PostMapping public ApiResponse<ProjectResponse> create(@AuthenticationPrincipal Jwt j,@Valid @RequestBody ProjectRequest r){return ApiResponse.success("Project created successfully.",response(service.create(users.synchronize(j),r)));}@PutMapping("/{id}") public ApiResponse<ProjectResponse> update(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid @RequestBody ProjectRequest r){return ApiResponse.success("Project updated successfully.",response(service.update(users.synchronize(j),id,r)));}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){service.delete(users.synchronize(j),id);return ApiResponse.success("Project deleted successfully.",null);}}
